import Foundation

enum TendiesTemplate {
    static func data(_ b64: String) -> Data { Data(base64Encoded: b64)! }

    static let complicationLayoutB64 = ""
    static let suggestionMetadataB64 = ""
    static let configurableOptionsB64 = ""
    static let homescreenConfigurationB64 = ""

    static var complicationLayout: Data { data(complicationLayoutB64) }
    static var suggestionMetadata: Data { data(suggestionMetadataB64) }
    static var configurableOptions: Data { data(configurableOptionsB64) }
    static var homescreenConfiguration: Data { data(homescreenConfigurationB64) }
}
